<?php
declare(strict_types=1);
final class ToolResultMailer {
 private ToolCalculator $calculator; public function __construct(?ToolCalculator $calculator=null){$this->calculator=$calculator??new ToolCalculator();}
 public function render(string $tool,array $raw,?string $confirmUrl=null,?string $deleteUrl=null):array{$data=$this->calculator->calculate($tool,$raw);$name=$this->name($tool);$sentence=$this->sentence($data);$lines=[$sentence,'','Inputs:'];foreach($data['inputs'] as $k=>$v)$lines[]=$k.': '.$v;$lines[]='';$lines[]='Ittai works this out from your real time clock and receipts.';if($confirmUrl)$lines[]='Confirm and save my numbers: '.$confirmUrl;if($deleteUrl)$lines[]='Delete my saved numbers: '.$deleteUrl;$lines[]='';$lines[]=defined('ITTAI_MAIL_POSTAL')?(string)ITTAI_MAIL_POSTAL:'Ittai, Vancouver, BC';$plain=implode("\n",$lines);$html='<p>'.htmlspecialchars($sentence,ENT_QUOTES,'UTF-8').'</p><h2>Inputs</h2><ul>';foreach($data['inputs'] as $k=>$v)$html.='<li>'.htmlspecialchars($k,ENT_QUOTES,'UTF-8').': '.htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8').'</li>';$html.='</ul><p>Ittai works this out from your real time clock and receipts.</p>';if($confirmUrl)$html.='<p><a href="'.htmlspecialchars($confirmUrl,ENT_QUOTES,'UTF-8').'">Confirm and save my numbers</a></p>';if($deleteUrl)$html.='<p><a href="'.htmlspecialchars($deleteUrl,ENT_QUOTES,'UTF-8').'">Delete my saved numbers</a></p>';$html.='<p>'.htmlspecialchars(defined('ITTAI_MAIL_POSTAL')?(string)ITTAI_MAIL_POSTAL:'Ittai, Vancouver, BC',ENT_QUOTES,'UTF-8').'</p>';return ['subject'=>'Your '.$name.' result from Ittai','html'=>$html,'plain'=>$plain,'data'=>$data];}
 private function name(string $tool):string{return ['labour-cost'=>'labour cost','markup-margin'=>'markup and margin','break-even'=>'break-even','mow-price'=>'mow price'][$tool]??'calculator';}
 public function sentence(array $d):string{$r=$d['result'];switch($d['tool']){case'labour-cost':return 'Each hour you bill costs you $'.number_format($r['costBilled'],2).'.';case'markup-margin':$sentence=$r['mode']==='markup'?'A '.number_format($r['markup']*100,2).'% markup keeps you '.number_format($r['margin']*100,2).'% of the price.':'To keep '.number_format($r['margin']*100,2).'%, mark up by '.number_format($r['markup']*100,2).'%. ';return $r['price']===null?$sentence:$sentence.' On $'.number_format($d['inputs']['cost'],2).', charge $'.number_format($r['price'],2).' and keep $'.number_format($r['profit'],2).'.';case'break-even':return $r['hours']===null?'At this rate each hour costs more than it brings in, so no number of hours breaks even.':'You need '.number_format($r['hours'],1).' billed hours a month (about '.number_format($r['perWeek'],1).' a week) before you earn anything.';default:return 'Charge $'.number_format($r['final'],2).' for this mow.';}}
}
